using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PurifyEffectBasedCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PurifyEffectBasedCustomDescription", order = 0)]
public class PurifyEffectBasedCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		PurifyEffectBasedAction purifyEffectBasedAction = battleAction as PurifyEffectBasedAction;
		string rawLocalizedDescription = GetRawLocalizedDescription(battleAction);
		string actionDescription = purifyEffectBasedAction.PurifyAction.GetActionDescription(purifyEffectBasedAction.BasePurifyAmount);
		string text = Smart.Format(base.localizationManager.GetLocalizedAdditionalPurify(), GetAmountWithUnlockablesModification(amountModified), rawLocalizedDescription);
		return actionDescription + "\n" + text;
	}
}
